mapper.select:
SELECT user_id
FROM agent_session_meta
WHERE tenant_id = #{tenantId}
  AND session_id = #{sessionId}
  AND user_id != #{userId}
LIMIT 1

mapper.update:
UPDATE agent_session_meta
SET last_run_id = #{runId}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}

mapper.select:
SELECT session_id, title, channel, status, last_run_id, message_count, last_active_at
FROM agent_session_meta
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
LIMIT 1
